import UserPage from 'flarum/forum/components/UserPage';
import { FlamePanel } from '../../common/streak/panels';
/** Profile → Streak: the member's whole flame. Its own chunk. */
export default class StreakUserPage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  content() {
    return this.user ? m(FlamePanel, {
      user: this.user
    }) : null;
  }
}
flarum.reg.add('ernestdefoe-cadence', 'forum/streak/StreakUserPage', StreakUserPage);